const m=.0066943799901413165,w=Math.PI/180;var f=class{constructor(t){const s=w*6378.137*1e3,i=Math.cos(t*w),n=1/(1-m*(1-i*i)),k=Math.sqrt(n);this.kx=s*k*i,this.ky=s*k*n*.9933056200098587}distance(t,s){const i=this.wrap(t[0]-s[0])*this.kx,n=(t[1]-s[1])*this.ky;return Math.sqrt(i*i+n*n)}pointOnLine(t,s){let i=1/0,n,k,x,y;for(let h=0;h<t.length-1;h++){let a=t[h][0],c=t[h][1],r=this.wrap(t[h+1][0]-a)*this.kx,o=(t[h+1][1]-c)*this.ky,e=0;(r!==0||o!==0)&&(e=(this.wrap(s[0]-a)*this.kx*r+(s[1]-c)*this.ky*o)/(r*r+o*o),e>1?(a=t[h+1][0],c=t[h+1][1]):e>0&&(a+=r/this.kx*e,c+=o/this.ky*e)),r=this.wrap(s[0]-a)*this.kx,o=(s[1]-c)*this.ky;const l=r*r+o*o;l<i&&(i=l,n=a,k=c,x=h,y=e)}return{point:[n,k],index:x,t:Math.max(0,Math.min(1,y))}}wrap(t){for(;t<-180;)t+=360;for(;t>180;)t-=360;return t}};export{f as CheapRuler};
